package edu.synergy.algorithms.finalproject;
import java.nio.file.*;import java.io.*;import java.util.*;
public final class StudentJsonRepository { public record Input(Student[] students){} @SuppressWarnings("unchecked") /** Time: O(k + n), where k is JSON length. */ public Input read(Path path)throws IOException{Object rootObj=MiniJson.parse(Files.readString(path));if(!(rootObj instanceof Map<?,?>root))throw new IllegalArgumentException("root object");int count=((Number)root.get("count")).intValue();List<Object>rows=(List<Object>)root.get("students");if(rows.size()!=count)throw new IllegalArgumentException("count mismatch");Student[]students=new Student[count];for(int i=0;i<count;i++){Map<String,Object>r=(Map<String,Object>)rows.get(i);students[i]=new Student((String)r.get("firstName"),(String)r.get("lastName"),(String)r.get("middleName"),(String)r.get("faculty"),((Number)r.get("grade")).intValue());}return new Input(students);} /** Time: O(n) excluding string lengths. */ public void write(Path path,Student golden,Map<Integer,List<Student>>groups)throws IOException{StringBuilder b=new StringBuilder("{\n  \"goldenStudent\": ").append(MiniJson.quote(golden.fullName())).append(",\n  \"grades\": {");boolean fg=true;for(var e:groups.entrySet()){if(!fg)b.append(',');fg=false;b.append("\n    ").append(MiniJson.quote(Integer.toString(e.getKey()))).append(": [");boolean fs=true;for(Student s:e.getValue()){if(!fs)b.append(',');fs=false;b.append("{\"fullName\":").append(MiniJson.quote(s.fullName())).append(",\"faculty\":").append(MiniJson.quote(s.faculty())).append(",\"grade\":").append(s.grade()).append('}');}b.append(']');}b.append("\n  }\n}\n");Files.writeString(path,b.toString());} }
